<script setup lang="ts">
import {ref,onMounted,watch} from 'vue';import {api} from './api';import ResultView from './ResultView.vue';import Dialog from './Dialog.vue';
const props=defineProps<{project?:any,admin?:boolean}>();const emit=defineEmits(['message']);const data=ref<any>({items:[],total:0,page:1}),page=ref(1),service=ref(''),subject=ref(''),status=ref(''),deviceID=ref(''),errorCode=ref(''),projectID=ref(''),projects=ref<any[]>([]),detail=ref<any>(null),busy=ref(false);
async function load(){busy.value=true;try{const q=new URLSearchParams({page:String(page.value),page_size:'20',service:service.value,subject:subject.value,status:status.value,project_id:projectID.value,device_id:deviceID.value,error_code:errorCode.value});data.value=await api((props.project?`/projects/${props.project.key}/invocations`:'/admin/invocations')+'?'+q)}catch(e:any){emit('message',e.message)}finally{busy.value=false}}
onMounted(async()=>{if(props.admin&&!props.project)projects.value=await api('/admin/projects');await load()});watch(()=>props.project?.id,()=>{page.value=1;load()});
</script>
<template><section><div v-if="!project" class="section-title"><div><p class="eyebrow">ACTIVITY LOG</p><h1>调用记录</h1><p class="muted">追溯调用主体、参数、结果与执行时的绑定快照。</p></div></div><form class="filter-bar" @submit.prevent="page=1;load()"><label v-if="admin&&!project">项目<select v-model="projectID"><option value="">全部项目</option><option v-for="p in projects" :key="p.id" :value="p.id">{{p.display_name}}</option></select></label><label>服务标识<input v-model="service" placeholder="全部服务"></label><label>主体 ID<input v-model="subject" placeholder="全部主体"></label><label v-if="admin">设备 ID<input v-model="deviceID" placeholder="全部设备"></label><label>错误码<input v-model="errorCode" placeholder="全部错误"></label><label>状态<select v-model="status"><option value="">全部状态</option><option value="succeeded">成功</option><option value="failed">失败</option><option value="running">执行中</option><option value="interrupted">已中断</option></select></label><button :disabled="busy">筛选记录</button></form><div class="table-wrap"><table><thead><tr><th>时间 / 服务</th><th>主体</th><th>状态</th><th>耗时</th><th>详情</th></tr></thead><tbody><tr v-for="r in data.items" :key="r.request_id"><td><strong>{{r.project||'设备调试'}} / {{r.service}}</strong><br><small>{{new Date(r.started_at).toLocaleString()}}</small></td><td><small>{{r.subject_kind}}<br>{{r.subject_id}}</small></td><td><span class="badge" :class="r.status==='succeeded'?'online':'error'">{{({succeeded:'成功',failed:'失败',running:'执行中',interrupted:'已中断'} as any)[r.status]}}</span></td><td>{{r.duration_ms}} ms</td><td><button @click="detail=r">查看</button></td></tr></tbody></table><div v-if="!data.items.length" class="empty compact">暂无符合条件的调用记录</div></div><div class="pagination"><span>共 {{data.total}} 条 · 第 {{page}} 页</span><div class="row"><button :disabled="page===1||busy" @click="page--;load()">上一页</button><button :disabled="page*20>=data.total||busy" @click="page++;load()">下一页</button></div></div><Dialog v-if="detail" title="调用详情" @close="detail=null"><ResultView :record="detail"/><h3>执行时绑定快照</h3><dl class="result-values"><dt>设备 ID</dt><dd>{{detail.device_id}}</dd><dt>设备服务</dt><dd>{{detail.device_service_key}}</dd><dt>服务版本</dt><dd>{{detail.service_revision}}</dd></dl><h3>参数</h3><pre>{{JSON.stringify(detail.parameters,null,2)}}</pre></Dialog></section></template>
